const campoIdade = document.querySelector('#idade');
campoIdade.min = 18;
campoIdade.max = 120;
campoIdade.required = true;

// O evento "invalid" dispara automaticamente quando o browser
// deteta que o campo não cumpre as suas restrições nativas
campoIdade.addEventListener('invalid', (evento) => {
  console.log('Valor inválido:', evento.target.value);
  console.log('Mensagem nativa:', evento.target.validationMessage);
});

function validarPasswords(password, confirmacao) {
  if (password.length < 8) {
    return 'A password tem de ter pelo menos 8 carateres.';
  }
  if (password !== confirmacao) {
    return 'As passwords não coincidem.';
  }
  return '';
}

const form = document.querySelector('#registo');

form.addEventListener('submit', (evento) => {
  const password = form.password.value;
  const confirmacao = form.confirmarPassword.value;
  const erro = validarPasswords(password, confirmacao);

  if (erro) {
    evento.preventDefault();
    form.confirmarPassword.setCustomValidity(erro);
    form.confirmarPassword.reportValidity();
  } else {
    form.confirmarPassword.setCustomValidity('');
  }
});

const emailInput = document.querySelector('#email');

emailInput.addEventListener('input', () => {
  if (emailInput.validity.valueMissing) {
    emailInput.setCustomValidity('O email é obrigatório.');
  } else if (emailInput.validity.typeMismatch) {
    emailInput.setCustomValidity('Introduza um email válido, como nome@exemplo.pt.');
  } else {
    emailInput.setCustomValidity('');
  }
});

const form = document.querySelector('#registo');

form.addEventListener('submit', (evento) => {
  if (!form.checkValidity()) {
    evento.preventDefault();
    form.reportValidity();
  }
});

const form = document.querySelector('#registo');

form.addEventListener('submit', async (evento) => {
  evento.preventDefault();

  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }

  const dados = new FormData(form);

  for (const [nome, valor] of dados.entries()) {
    console.log(`${nome}: ${valor}`);
  }

  const objeto = Object.fromEntries(dados.entries());

  const resposta = await fetch('/api/registo', {
    method: 'POST',
    body: JSON.stringify(objeto),
    headers: { 'Content-Type': 'application/json' },
  });

  console.log('Estado da resposta:', resposta.status);
});

const form = document.querySelector('#contacto');

function validarFormulario(form) {
  const mensagem = form.telefone.value.trim().length === 9
    ? ''
    : 'O telefone deve ter 9 dígitos.';
  form.telefone.setCustomValidity(mensagem);
  return form.checkValidity();
}

form.telefone.addEventListener('input', () => validarFormulario(form));

form.addEventListener('submit', (evento) => {
  evento.preventDefault();

  if (!validarFormulario(form)) {
    form.reportValidity();
    return;
  }

  const dados = Object.fromEntries(new FormData(form).entries());
  console.log('Pronto a enviar:', dados);
});

