const form = document.querySelector('#registo');
const password = form.querySelector('#password');
const confirmarPassword = form.querySelector('#confirmarPassword');

function validarConfirmacao() {
  if (password.value !== confirmarPassword.value) {
    confirmarPassword.setCustomValidity('As passwords não coincidem.');
  } else {
    confirmarPassword.setCustomValidity('');
  }
}

password.addEventListener('input', validarConfirmacao);
confirmarPassword.addEventListener('input', validarConfirmacao);

form.addEventListener('submit', (evento) => {
  evento.preventDefault();

  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }

  console.log('Registo válido');
});

const form = document.querySelector('#reserva');

form.addEventListener('submit', async (evento) => {
  evento.preventDefault();

  const dataInicio = form.dataInicio;
  const dataFim = form.dataFim;

  if (dataFim.value <= dataInicio.value) {
    dataFim.setCustomValidity('A data de fim tem de ser posterior à data de início.');
  } else {
    dataFim.setCustomValidity('');
  }

  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }

  const dados = Object.fromEntries(new FormData(form).entries());

  const resposta = await fetch('/api/reservas', {
    method: 'POST',
    body: JSON.stringify(dados),
    headers: { 'Content-Type': 'application/json' },
  });

  console.log('Estado da resposta:', resposta.status);
});
